def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, 35.0))
        return float(min(budget, 12.0))

    prev_bids = []
    rich_aggressive = 0
    desperate_count = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if bid >= 85:
                rich_aggressive += 1
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = float(supply) <= 18.0
    abundant = float(supply) >= 22.0

    if hp <= 2 or no_water_days >= 2:
        if highest_prev >= 90:
            bid = 92.0
        elif highest_prev >= 75:
            bid = highest_prev + 2.0
        else:
            bid = 68.0 if scarcity else 58.0
        return float(min(budget, bid))

    if hp <= 4 or no_water_days >= 1:
        if scarcity:
            if highest_prev >= 88:
                bid = 72.0
            elif highest_prev >= 60:
                bid = highest_prev + 1.5
            else:
                bid = 52.0
        else:
            if highest_prev >= 88:
                bid = 48.0
            elif highest_prev >= 60:
                bid = highest_prev * 0.82
            else:
                bid = 38.0
        return float(min(budget, bid))

    if rich_aggressive >= 2:
        if abundant:
            bid = 9.0
        elif scarcity:
            bid = 18.0
        else:
            bid = 13.0
    else:
        if highest_prev >= 80:
            bid = 16.0 if hp >= 6 else 34.0
        elif highest_prev >= 40:
            bid = max(22.0, avg_prev * 0.7)
        else:
            bid = 26.0 if scarcity else 20.0

    if desperate_count >= 2:
        bid += 6.0
    elif desperate_count == 1:
        bid += 3.0

    if day >= 8 and hp >= 6:
        bid *= 0.85

    bid = max(0.0, min(budget, bid))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 10.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        avg_prev = sum(yesterday_bids) / len(yesterday_bids)
        target_bid = min(max_prev + 2.0, avg_prev * 1.1)
    else:
        target_bid = DAILY_SALARY * 0.4

    if my_status['hp'] < 4:
        return min(my_status['budget'], max(target_bid, DAILY_SALARY * 0.8))

    if supply < (len(alive_opponents) + 1) * WATER_REQ:
        return min(my_status['budget'], max(target_bid, DAILY_SALARY * 0.6))

    return min(my_status['budget'], max(target_bid * 0.8, 15.0))
